from collections import deque, Counter
def comps(g):
    H,W=len(g),len(g[0]); bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if g[y][x]!=bg and (y,x) not in seen:
                q=deque([(y,x)]); cc=[]
                while True:
                    cy,cx=q.popleft()
                    if (cy,cx) in seen or g[cy][cx]==bg: continue
                    seen.add((cy,cx)); cc.append((cy,cx))
                    for dy,dx in [(0,1),(0,-1),(1,0),(-1,0)]:
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]!=bg:
                            q.append((ny,nx))
                out.append(cc)
    return sorted(out,key=lambda c:-len(c)), bg

def solve(inp, bg=None):
    g=np.array(inp)
    if bg is None: bg=collections.Counter(v for row in g for v in row).most_common(1)[0][0]
    cs,bg=comps(g)
    big=cs[-1]; markers=cs[:-1]
    # template: bounding box of big component
    rs=[p[0] for p in big]; csrs=[p[1] for p in big]
    minr,minc=min(rs),min(csrs); maxr,maxc=max(rs),max(csrs)
    th,hw=max(maxr-minr+1,maxc-minc+1),maxc-minc+1
    T=g[minr:maxr+1,minc:maxc+1]
    H,W=g.shape
    res=[[v for v in row] for row in inp]
    for ry,cx in markers:
        for i in range(th):
            for j in range(hw):
                ny,nx=ry+i,cx+j
                if 0<=ny<H and 0<=nx<W: res[ny][nx]=T[i][j]
    return [row[:] for row in res]

