from collections import Counter, deque

def f(inp):
    H,W=len(inp),len(inp[0]); bg=Counter(v for row in inp for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for y in range(H):
        for x in range(W):
            if inp[y][x]!=bg and (y,x) not in seen:
                q=deque([(y,x)]); cc=[]
                while True:
                    cy,cx=q.popleft()
                    if (cy,cx) in seen or inp[cy][cx]==bg: continue
                    seen.add((cy,cx)); cc.append((cy,cx))
                    ndirs=[(0,1),(0,-1),(1,0),(-1,0)]
                    for dy,dx in ndirs:
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and inp[ny][nx]!=bg:
                            q.append((ny,nx))
                comps.append(cc)
    cs=sorted(comps,key=lambda c:-len(c))
