    minc=min(p[1] for p in big); maxc=max(p[1] for p in big)
    th=h=max(maxr-minr+1,maxc-minc+1); mw=maxc-minc+1
    T=np.array([[inp[r][c] for c in range(minc,minc+mw)] for r in range(minr,minr+th)])
