    big=cs[-1]; markers=cs[:-1]
    rs=[p[0] for p in big]; csrs=[p[1] for p in big]
    minr,minc=min(rs),min(csrs); maxr,maxc=max(rs),max(csrs)
    th,hw=max(maxr-minr+1,maxc-minc+1),maxc-minc+1
    T=np.array([[inp[r][c] for c in range(minc,minc+hw)] for r in range(minr,minr+th)])
