def comps(g, bg):
    seen=set(); out=[]
    H,W=len(g),len(g[0])
    for y in range(H):
        for x in range(W):
            if g[y][x]!=bg and (y,x) not in seen:
                cc=[]; stack=[(y,x)]
                while stack:
