                    if (cy,cx) in seen or g[cy][cx]==bg: continue
                    seen.add((cy,cx)); cc.append((cy,cx))
                    for dy,dx in [(0,1),(0,-1),(1,0),(-1,0)]:
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]!=bg:
