# The rule from earlier demo6 analysis that worked for demo6: stamp centered on each single-cell marker.
# But I had bugs. Let me build it cleanly in one cell and test all demos.
def solve(g):
    A=np.array(g); H,W=len(A),len(A[0]); cnt=collections.Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    # connected components, color-agnostic but cells of any non-bg color count together
    seen=set(); comp=[]
    for y in range(H):
        for x in range(W):
            if A[y,x]!=bg and (y,x) not in seen:
                stack=[(y,x)]; cc=[]; color=None
                while stack:
                    cy,cx=stack.pop()
                    if (cy,cx) in seen or A[cy,cx]==bg: continue
                    c=A[cy,cx]; cc.append((cy,cx))
                    if color is None and c!=bg: color=c
                    for dy,dx in [(0,1),(0,-1),(1,0),(-1,0)]:
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and A[ny,nx]!=bg:
                            stack.append((ny,nx))
                comp.append((cc, color))
    csorted=sorted(comp, key=lambda c: (-len(c[0]), -hash(c)))
    big=csorted[-1]; markers=csorted[:-1]
    rs=[p[0] for p in big]; csrs=[p[1] for p in big]
    minr,minc=min(rs),min(csrs); maxr,maxc=max(rs),max(csrs)
    th=h=max(maxr-minr+1,maxc-minc+1); wv=w=maxc-minc+1
    T=[[A[r][c] for c in range(minc,minc+wv)] for r in range(minr,minr+th)]
    out=[row[:] for row in g]
    for ry,mx in markers:
        ty,tx=ry-th//2,mx-wv//2
        for i in range(th):
            for j in range(wv):
                ny,nx=ty+i,tx+j
                if 0<=ny<H and 0<=nx<W: out[ny][nx]=T[i][j]
    return [row[:] for row in out]

matches=True
for key in ['Demo pair 5','Demo pair 6','Demo pair 7','Demo pair 8']:
    pred=solve(G[key+' input']); exp=G[key+' output']
    print(key, "MATCH" if pred==exp else "FAIL")
    matches=matches and (pred==exp)
print("ALL:", matches)

